import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

namespace {

constexpr int TILE = 32;

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K,
    int N
) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    constexpr int ROWS_PER_THREAD = TILE / (TILE / 4);
    constexpr int COLS_PER_THREAD = 4;
    const int col_in_tile = tx * COLS_PER_THREAD;
    const int row_base = ty;
    float acc[ROWS_PER_THREAD][COLS_PER_THREAD];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_THREAD; ++r) {
        #pragma unroll
        for (int q = 0; q < COLS_PER_THREAD; ++q) {
            acc[r][q] = 0.0f;
        }
    }
    const int tiles = (K + TILE - 1) / TILE;
    for (int tile = 0; tile < tiles; ++tile) {
        for (int load_iter = 0; load_iter < 4; ++load_iter) {
            const int smem_row = load_iter * (TILE / 4) + ty;
            const int a_row = blockIdx.y * TILE + smem_row;
            const int a_col = tile * TILE + col_in_tile;
            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int c = a_col + q;
                As[smem_row][col_in_tile + q] =
                    (a_row < M && c < K) ? A[a_row * K + c] : 0.0f;
            }
            const int b_row = tile * TILE + smem_row;
            const int b_col = blockIdx.x * TILE + col_in_tile;
            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int c = b_col + q;
                Bs[smem_row][col_in_tile + q] =
                    (b_row < K && c < N) ? B[b_row * N + c] : 0.0f;
            }
        }
        __syncthreads();
        #pragma unroll
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            #pragma unroll
            for (int r = 0; r < ROWS_PER_THREAD; ++r) {
                const int smem_row = r * (TILE / 4) + row_base;
                const float a = As[smem_row][k];
                #pragma unroll
                for (int q = 0; q < COLS_PER_THREAD; ++q) {
                    acc[r][q] = fmaf(
                        a, Bs[k][col_in_tile + q], acc[r][q]);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int r = 0; r < ROWS_PER_THREAD; ++r) {
        const int row = blockIdx.y * TILE + r * (TILE / 4) + row_base;
        if (row < M) {
            #pragma unroll
            for (int q = 0; q < COLS_PER_THREAD; ++q) {
                const int col = blockIdx.x * TILE + col_in_tile + q;
                if (col < N) {
                    C[row * N + col] = acc[r][q];
                }
            }
        }
    }
}

} // namespace

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    const dim3 block(TILE / 4, TILE / 4);
    const dim3 grid(
        (N + TILE - 1) / TILE,
        (M + TILE - 1) / TILE
    );

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_kernel<<<grid, block, 0, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K,
        N
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

_matmul_ext = load_inline(
    name="custom_cuda_matmul_extension",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_ext.matmul_cuda(A, B)

